import{_ as o,r as a,o as p,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"{% content %} - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Variables","slug":"variables","link":"#variables","children":[]},{"level":2,"title":"Setting Contents to a Twig Variable","slug":"setting-contents-to-a-twig-variable","link":"#setting-contents-to-a-twig-variable","children":[]},{"level":2,"title":"Checking a Content File Exists","slug":"checking-a-content-file-exists","link":"#checking-a-content-file-exists","children":[]}],"relativePath":"2.x/markup/tag-content.md","filePath":"2.x/markup/tag-content.md"}'),u={name:"2.x/markup/tag-content.md"};function g(r,n,k,d,m,w){const t=a("pre-heading"),e=a("post-heading");return p(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"{% content %}",-1)),s(e),n[1]||(n[1]=i(`<p>The <code>{% content %}</code> tag will display a <a href="./../cms/content.html">CMS content block</a> on the page. To display content block called <strong>contacts.htm</strong> you pass the file name after the <code>content</code> tag quoted as a string.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>contacts.htm<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>A content block inside a subdirectory can be rendered in the same way.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar/content.htm<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><blockquote><p><strong>Note</strong>: The <a href="./../cms/themes.html#oc-subdirectories">Themes documentation</a> has more details on subdirectory usage.</p></blockquote><p>Content blocks can be rendered as plain text:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>readme.txt<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>You can also use Markdown syntax:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>changelog.md<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Content blocks can also be used in combination with <a href="./../cms/layouts.html#oc-placeholders">layout placeholders</a>:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> sidebar <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>sidebar-content.htm<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="variables"><a href="#variables" class="header-anchor">#</a> Variables</h2><p>You can pass variables to content blocks by specifying them after the file name:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>welcome.htm<span class="token punctuation">&quot;</span></span> name<span class="token operator">=</span>user<span class="token punctuation">.</span>name <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>You can also assign new variables for use in the content:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>location.htm<span class="token punctuation">&quot;</span></span> city<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Vancouver<span class="token punctuation">&quot;</span></span> country<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Canada<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Inside the content, variables can be accessed using a basic syntax using singular <em>curly brackets</em>:</p><div class="language- extra-class"><pre class="language-text"><code>&lt;p&gt;Country: {country}, city: {city}.&lt;/p&gt;
</code></pre></div><p>You can also pass a collection of variables as a simple array:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&quot;</span>welcome.htm<span class="token punctuation">&quot;</span></span> likes<span class="token operator">=</span><span class="token punctuation">[</span>
    <span class="token punctuation">{</span>name<span class="token punctuation">:</span><span class="token string"><span class="token punctuation">&#39;</span>Dogs<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span>name<span class="token punctuation">:</span><span class="token string"><span class="token punctuation">&#39;</span>Fishing<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span>name<span class="token punctuation">:</span><span class="token string"><span class="token punctuation">&#39;</span>Golf<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span>
<span class="token punctuation">]</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>The collection of variables is accessed by using an opening and closing set of brackets:</p><div class="language- extra-class"><pre class="language-text"><code>&lt;ul&gt;
    {likes}
        &lt;li&gt;{name}&lt;/li&gt;
    {/likes}
&lt;/ul&gt;
</code></pre></div><blockquote><p><strong>Note</strong>: Twig syntax is not supported in Content blocks, consider using a <a href="./../cms/partials.html">CMS partial</a> instead.</p></blockquote><h2 id="setting-contents-to-a-twig-variable"><a href="#setting-contents-to-a-twig-variable" class="header-anchor">#</a> Setting Contents to a Twig Variable</h2><p>In any template you can set the contents to a variable with the <code>content()</code> function. This lets you manipulate the output before display. Remember to use the <code>|raw</code> filter to prevent output escaping.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> welcomeContent <span class="token operator">=</span> content<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> welcomeContent<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>You may also pass variables to the content as the second argument.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> welcomeContent <span class="token operator">=</span> content<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">{</span> foo<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>bar<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="checking-a-content-file-exists"><a href="#checking-a-content-file-exists" class="header-anchor">#</a> Checking a Content File Exists</h2><p>The <code>hasContent()</code> function can be used to check if a content exists without rendering the contents. To prevent the rendering of the content, pass the second argument as false and it will return true or false if the content file is found.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> hasContent<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Welcome content not found!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div>`,31))])}const v=o(u,[["render",g]]);export{b as __pageData,v as default};
